<?php require_once '../config/config.php';$title='Community Cookbook';$rs=db()->query("SELECT r.*,CONCAT(u.first_name,' ',u.last_name) author FROM recipes r LEFT JOIN users u ON u.id=r.author_id WHERE r.status='approved' AND r.author_id IS NOT NULL ORDER BY r.created_at DESC")->fetchAll();require '../includes/header.php';?><div class="page-hero"><div class="container"><span class="eyebrow">Cook together</span><h1 class="fw-bold">Community Cookbook</h1><p class="lead">Recipes shared by FoodFusion members.</p><?php if(user()):?><a class="btn btn-primary" href="submit-recipe.php">Share a recipe</a><?php else:?><a class="btn btn-primary" href="../login.php">Log in to contribute</a><?php endif;?></div></div><section class="section"><div class="container"><div class="row g-4"><?php foreach($rs as $r):?><div class="col-md-6 col-lg-4"><div class="card recipe-card"><img src="<?=recipe_image($r['image'])?>" alt=""><div class="card-body"><span class="tag">Community</span><h5 class="mt-3"><?=e($r['title'])?></h5><p><?=e($r['description'])?></p><small>Shared by <?=e($r['author'])?></small><a href="recipe.php?id=<?=$r['id']?>" class="stretched-link"></a></div></div></div><?php endforeach;?></div></div></section><?php require '../includes/footer.php';?>